def minion_game(string):
    vowels = "AEIOU"
    n = len(string)
    stuart_score = 0
    kevin_score = 0

    # Count substrings starting with consonants (Stuart)
    for i in range(n):
        if string[i] not in vowels:
            # Each position can be the start of multiple substrings
            stuart_score += (n - i)

    # Count substrings starting with vowels (Kevin)
    for i in range(n):
        if string[i] in vowels:
            kevin_score += (n - i)

    if stuart_score > kevin_score:
        print(f"Stuart {stuart_score}")
    elif kevin_score > stuart_score:
        print(f"Kevin {kevin_score}")
    else:
        print("Draw")

# Read input
s = input().strip()
minion_game(s)
